create table if not exists habitflow.support_tickets(id uuid primary key,user_id uuid references habitflow.users(id),protocol varchar(50) unique not null,type varchar(50) not null,status varchar(50) not null,priority varchar(50) not null,title varchar(200),description text,source varchar(50),created_at timestamp not null,updated_at timestamp not null,resolved_at timestamp null);
create table if not exists habitflow.support_messages(id uuid primary key,ticket_id uuid references habitflow.support_tickets(id),user_id uuid null,role varchar(50),message text,is_sensitive_blocked boolean default false,created_at timestamp not null);
